// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(0) && actor != address(c));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // move well past the target block so settle is admissible
        vm.roll(block.number + 10);

        bool ok1;
        vm.prank(actor);
        try c.settle() {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        assertTrue(ok1, "first settle should be admissible");

        // the guess slot must be consumed: a second settle for the same
        // player can never be admissible, for ANY actor and ANY guess hash
        bool ok2;
        vm.prank(actor);
        try c.settle() {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        assertTrue(!ok2, "second settle must revert: guess slot was cleared");
    }
}
